export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const existing = await getBooking(id);

  const roomId = input.roomId ?? existing.roomId;
  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : existing.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : existing.endsAt;

  const scheduleChanged =
    roomId !== existing.roomId ||
    startsAt.getTime() !== existing.startsAt.getTime() ||
    endsAt.getTime() !== existing.endsAt.getTime();

  if (existing.status !== BOOKING_CANCELLED && scheduleChanged) {
