  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that starts before and ends inside an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Straddling start');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that fully contains an active booking', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Engulfing');
    expect(response.statusCode).toBe(409);
  });

  it('rejects updating a booking into a slot taken by another booking', async () => {
    await book(24, 25);
    const second = await book(26, 27, 'Second');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('allows updating a cancelled booking into a slot taken by another booking', async () => {
    const first = await book(24, 25);
    await app.inject({ method: 'POST', url: `/bookings/${first.json().id}/cancel` });
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${first.json().id}`,
      payload: { title: 'Still cancelled' },
    });
    expect(response.statusCode).toBe(200);
  });

  describe('availability', () => {
    it('requires the room to exist', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=missing&from=${inHours(0)}&to=${inHours(2)}&durationMinutes=30`,
      });
      expect(response.statusCode).toBe(404);
    });

    it('rejects a range where "from" is not before "to"', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(2)}&to=${inHours(0)}&durationMinutes=30`,
      });
      expect(response.statusCode).toBe(400);
    });

    it('returns the whole window as a slot when nothing is booked', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(0)}&to=${inHours(1)}&durationMinutes=60`,
      });
      expect(response.statusCode).toBe(200);
      expect(response.json().data).toHaveLength(1);
    });

    it('excludes booked ranges and offers slots around them', async () => {
      await book(1, 2);
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(0)}&to=${inHours(3)}&durationMinutes=60`,
      });
      const slots = response.json().data;
      expect(slots).toHaveLength(2);
      expect(new Date(slots[0].startsAt).getTime()).toBeCloseTo(new Date(inHours(0)).getTime(), -2);
      expect(new Date(slots[1].startsAt).getTime()).toBeCloseTo(new Date(inHours(2)).getTime(), -2);
    });

    it('does not offer a slot that does not fit the requested duration', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(0)}&to=${inHours(0.5)}&durationMinutes=60`,
      });
      expect(response.json().data).toHaveLength(0);
    });
  });
});

